def preencher_chamados_existentes(apps, schema_editor):
    """Chamados criados antes desta migration: o nº registrado pelo TI quer dizer
    que o chamado JÁ foi aberto no atendimento; os demais seguem "aguardando
    atendimento" (o default). A última atividade vira a data de criação, para a
    fila ordenar sem linha vazia. Sem reversão: os campos somem junto."""
    Chamado = apps.get_model("ProjetoEstoque", "ContratacaoChamado")
    Chamado.objects.exclude(identificador="").update(atendimento="aberto")
    Chamado.objects.filter(ultima_atividade_em__isnull=True).update(
        ultima_atividade_em=models.F("created_at"),
    )


